27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
37	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
38	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
47	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    private final TelephoneNormalizer telephoneNormalizer;
75	
76	    private final AddressNormalizer addressNormalizer;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper,
82	                                 TelephoneNormalizer telephoneNormalizer,
83	                                 AddressNormalizer addressNormalizer) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	        this.telephoneNormalizer = telephoneNormalizer;
89	        this.addressNormalizer = addressNormalizer;
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
95	        Collection<Owner> owners;
96	        if (lastName != null) {
97	            owners = this.clinicService.findOwnerByLastName(lastName);
98	        } else {
99	            owners = this.clinicService.findAllOwners();
100	        }
101	        if (owners.isEmpty()) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
110	        Owner owner = this.clinicService.findOwnerById(ownerId);
111	        if (owner == null) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        normalizeAndValidate(ownerFieldsDto);
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
124	        owner.setNamesakeCount(countNamesakes(owner));
125	        assignHousehold(owner, ownerFieldsDto);
126	        this.clinicService.saveOwner(owner);
127	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
128	        headers.setLocation(UriComponentsBuilder.newInstance()
129	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
130	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
131	    }
132	
133	    /**
134	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
135	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
136	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
137	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
138	     * it; the email is canonicalized; and a missing registration date defaults to the current date. The payload is
139	     * mutated in place so the caller can map and save it directly.
140	     *
141	     * @param ownerFieldsDto the incoming owner payload, mutated in place
142	     * @throws MissingOwnerFieldsException if any required field is missing or blank
143	     * @throws DuplicateTelephoneException if another owner already uses the normalized telephone
144	     */
145	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
146	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
147	        validateRequiredFields(ownerFieldsDto);
148	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
149	        ownerFieldsDto.setTelephone(telephone);
150	        requireUniqueTelephone(telephone);
151	        requireUniqueHousehold(ownerFieldsDto);
152	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
153	        if (ownerFieldsDto.getRegistrationDate() == null) {
154	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
155	        }
156	    }
157	
158	    /**
159	     * Builds an owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}. {@code CITY3} is the upper-cased
160	     * first three letters of the city, {@code LAST3} the upper-cased first three letters of the last name, and
161	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of owners already in that
162	     * city (e.g. {@code LON-SMI-0007}).
163	     *
164	     * @param city     the owner's city
165	     * @param lastName the owner's last name
166	     * @return the generated customer code
167	     */
168	    private String generateCustomerCode(String city, String lastName) {
169	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase();
170	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
171	        int sequence = (int) this.clinicService.findAllOwners().stream()
172	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
173	            .count() + 1;
174	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
175	    }
176	
177	    /**
178	     * Counts how many existing owners already share the given owner's first and last name, compared
179	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
180	     * create; it is zero when the owner's name is unique.
181	     *
182	     * @param owner the newly mapped owner about to be saved
183	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
184	     */
185	    private int countNamesakes(Owner owner) {
186	        String firstName = owner.getFirstName();
187	        String lastName = owner.getLastName();
188	        return (int) this.clinicService.findAllOwners().stream()
189	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
190	                && lastName.equalsIgnoreCase(existing.getLastName()))
191	            .count();
192	    }
193	
194	    /**
195	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
196	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
197	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
198	     *
199	     * @param ownerFieldsDto the owner payload to validate
200	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
201	     */
202	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
203	        List<String> missingFields = new ArrayList<>();
204	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
205	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
206	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
207	        requireText(missingFields, "city", ownerFieldsDto.getCity());
208	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
209	        if (!missingFields.isEmpty()) {
210	            throw new MissingOwnerFieldsException(missingFields);
211	        }
212	    }
213	
214	    private void requireText(List<String> missingFields, String fieldName, String value) {
215	        if (value == null || value.isBlank()) {
216	            missingFields.add(fieldName);
217	        }
218	    }
219	
220	    /**
221	     * Normalizes an optional owner email. A syntactically valid address is already enforced by Bean Validation on the
222	     * request payload, so this only canonicalizes the value that gets stored and returned by lower-casing it. A missing
223	     * (blank or {@code null}) email is left untouched, since the field is optional.
224	     *
225	     * @param email the raw email value from the request, may be {@code null}
226	     * @return the lower-cased email, or the original value when none was supplied
227	     */
228	    private String normalizeEmail(String email) {
229	        if (email == null || email.isBlank()) {
230	            return email;
231	        }
232	        return email.toLowerCase();
233	    }
234	
235	    /**
236	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
237	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
238	     * originally formatted.
239	     *
240	     * @param telephone the normalized telephone of the owner being created
241	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
242	     */
243	    private void requireUniqueTelephone(String telephone) {
244	        boolean inUse = this.clinicService.findAllOwners().stream()
245	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
246	            .anyMatch(telephone::equals);
247	        if (inUse) {
248	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
249	        }
250	    }
251	
252	    /**
253	     * Rejects creating an owner who shares a household (see {@link #findHouseholdMembers}) with an existing owner,
254	     * unless the request opts in by setting {@code sharesHousehold} to {@code true}.
255	     *
256	     * @param ownerFieldsDto the incoming owner payload
257	     * @throws DuplicateOwnerException if another owner already belongs to the same household and the request does not
258	     *                                 set {@code sharesHousehold}
259	     */
260	    private void requireUniqueHousehold(OwnerFieldsDto ownerFieldsDto) {
261	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
262	            return;
263	        }
264	        if (!findHouseholdMembers(ownerFieldsDto).isEmpty()) {
265	            throw new DuplicateOwnerException(
266	                "an owner with the same last name and address already exists in this household");
267	        }
268	    }
269	
270	    /**
271	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
272	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
273	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
274	     * incidental formatting differences and abbreviation variants do not affect membership.
275	     *
276	     * @param ownerFieldsDto the incoming owner payload
277	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
278	     *         them; empty when none match
279	     */
280	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
281	        String lastName = collapseWhitespace(ownerFieldsDto.getLastName());
282	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
283	        return this.clinicService.findAllOwners().stream()
284	            .filter(existing -> collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
285	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
286	            .toList();
287	    }
288	
289	    /**
290	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
291	     * space. Case is deliberately preserved here; callers compare the result case-insensitively.
292	     *
293	     * @param value the raw field value, may be {@code null}
294	     * @return the whitespace-collapsed value, or an empty string when {@code null}
295	     */
296	    private String collapseWhitespace(String value) {
297	        if (value == null) {
298	            return "";
299	        }
300	        return value.strip().replaceAll("\\s+", " ");
301	    }
302	
303	    /**
304	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
305	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
306	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
307	     * identifier is derived deterministically from the household's last name and address, so every member of the same
308	     * household resolves to the same stable value regardless of creation order. Existing members that predate the
309	     * feature and still lack the identifier are backfilled so the whole household shares it.
310	     *
311	     * @param owner          the newly mapped owner about to be saved
312	     * @param ownerFieldsDto the incoming owner payload
313	     */
314	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
315	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
316	            return;
317	        }
318	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
319	        if (members.isEmpty()) {
320	            return;
321	        }
322	        String householdId = generateHouseholdId(ownerFieldsDto);
323	        owner.setHouseholdId(householdId);
324	        for (Owner member : members) {
325	            if (!householdId.equals(member.getHouseholdId())) {
326	                member.setHouseholdId(householdId);
327	                this.clinicService.saveOwner(member);
328	            }
329	        }
330	    }
331	
332	    /**
333	     * Derives a household's stable identifier, formatted {@code HH-<12 hex chars>}, from the case-insensitive,
334	     * whitespace-collapsed last name and the normalized address (see {@link AddressNormalizer}). Being a pure function
335	     * of those fields, it is identical for every owner in the same household and never changes over time.
336	     *
337	     * @param ownerFieldsDto the incoming owner payload
338	     * @return the household identifier
339	     */
340	    private String generateHouseholdId(OwnerFieldsDto ownerFieldsDto) {
341	        String key = collapseWhitespace(ownerFieldsDto.getLastName()).toLowerCase()
342	            + "\n" + addressNormalizer.normalize(ownerFieldsDto.getAddress()).toLowerCase();
343	        try {
344	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
345	            StringBuilder hex = new StringBuilder();
346	            for (int i = 0; i < 6; i++) {
347	                hex.append(String.format("%02X", digest[i]));
348	            }
349	            return "HH-" + hex;
350	        } catch (NoSuchAlgorithmException ex) {
351	            throw new IllegalStateException("SHA-256 is not available", ex);
352	        }
353	    }
354	
355	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
356	    @Override
357	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
358	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
359	        if (currentOwner == null) {
360	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
361	        }
362	        currentOwner.setAddress(ownerFieldsDto.getAddress());
363	        currentOwner.setCity(ownerFieldsDto.getCity());
364	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
365	        currentOwner.setLastName(ownerFieldsDto.getLastName());
366	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
367	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
368	        this.clinicService.saveOwner(currentOwner);
369	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
370	    }
371	
372	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
373	    @Transactional
374	    @Override
375	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
376	        Owner owner = this.clinicService.findOwnerById(ownerId);
377	        if (owner == null) {
378	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
379	        }
380	        this.clinicService.deleteOwner(owner);
381	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
382	    }
383	
384	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
385	    @Override
386	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
387	        Owner owner = this.clinicService.findOwnerById(ownerId);
388	        if (owner == null) {
389	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
390	        }
391	        HttpHeaders headers = new HttpHeaders();
392	        Pet pet = petMapper.toPet(petFieldsDto);
393	        owner.setId(ownerId);
394	        pet.setOwner(owner);
395	        pet.getType().setName(null);
396	        this.clinicService.savePet(pet);
397	        PetDto petDto = petMapper.toPetDto(pet);
398	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
399	            .buildAndExpand(pet.getId()).toUri());
400	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
401	    }
402	
403	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
404	    @Override
405	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
406	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
407	        if (currentOwner != null) {
408	            Pet currentPet = this.clinicService.findPetById(petId);
409	            if (currentPet != null) {
410	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
411	                currentPet.setName(petFieldsDto.getName());
412	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
413	                this.clinicService.savePet(currentPet);
414	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
415	            }
416	        }
417	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
418	    }
419	
420	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
421	    @Override
422	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
423	        HttpHeaders headers = new HttpHeaders();
424	        Visit visit = visitMapper.toVisit(visitFieldsDto);
425	        Pet pet = new Pet();
426	        pet.setId(petId);
427	        visit.setPet(pet);
428	        this.clinicService.saveVisit(visit);
429	        VisitDto visitDto = visitMapper.toVisitDto(visit);
430	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
431	            .buildAndExpand(visit.getId()).toUri());
432	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
433	    }
434	
435	
436	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
437	    @Override
438	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
439	        Owner owner = this.clinicService.findOwnerById(ownerId);
440	        if (owner != null) {
441	            Pet pet = owner.getPet(petId);
442	            if (pet != null) {
443	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
444	            }
445	        }
446	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
447	    }
448	}
