@Mapping(target = "sharesHousehold", ignore = true)
OwnerDto toOwnerDto(Owner owner);

/**
 * Derives the canonical region for an owner's city using the fixed
 * city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD).
 * Any other (or missing) city resolves to "UNKNOWN".
 */
default String deriveLocality(String city) {
    if (city == null) {
        return "UNKNOWN";
    }
    return switch (city) {
        case "Sydney" -> "NSW";
        case "Melbourne" -> "VIC";
        case "Brisbane" -> "QLD";
        default -> "UNKNOWN";
    };
}

